  const vec4 ST_BANK_IR[16] = vec4[16](vec4(0.29412,8.33333,0.52632,0.000),vec4(0.30303,7.14286,0.55556,0.000),vec4(0.40000,8.33333,0.66667,0.000),vec4(0.35714,7.14286,0.62500,0.000),vec4(0.38462,2.94118,0.80645,1.000),vec4(0.52632,3.22581,1.12360,1.000),vec4(0.43478,2.56410,0.88496,1.000),vec4(0.62500,3.33333,1.11111,1.000),vec4(0.34483,3.12500,1.00000,1.000),vec4(0.45455,2.70270,0.88496,1.000),vec4(0.21739,2.38095,0.54054,1.000),vec4(0.26316,2.17391,0.74074,1.000),vec4(0.20833,2.56410,0.65789,1.000),vec4(0.29412,2.85714,0.60976,1.000),vec4(0.35714,2.08333,0.33333,1.000),vec4(0.43478,2.27273,0.30303,1.000));
